<?php /** @var array<string,mixed> $i */ /** @var list<array<string,mixed>> $items */ /** @var array<string,mixed> $bal */ /** @var list<array<string,mixed>> $payments */ /** @var array<string,mixed> $biz */ /** @var int $payable */ /** @var ?string $upiLink */ /** @var ?array<string,mixed> $upi */ /** @var string $today */ /** @var list<array<string,mixed>> $claims */
$url = '/my/invoices/' . $i['public_id']; $v = static fn (string $k, string $d = ''): string => old($k, $d); $labels = ['issued' => 'Unpaid', 'partially_paid' => 'Partly paid', 'paid' => 'Paid', 'void' => 'Void']; ?>
<div class="page-head"><div><p class="eyebrow">Invoice</p><h1><?= e($i['reference']) ?> · <?= e($i['title']) ?></h1></div><div class="actions"><a class="btn btn-ghost" href="<?= e($url) ?>/print">Print view</a><a class="btn btn-ghost" href="/my/invoices">&larr; My invoices</a></div></div>
<div class="panel"><div class="detail-grid"><div><span class="muted">Status</span><br><span class="badge badge-bi-<?= e($i['status']) ?>"><?= e($labels[$i['status']] ?? $i['status']) ?></span></div><div><span class="muted">Total</span><br><strong><?= e(money($i['total_minor'])) ?></strong></div>
    <div><span class="muted">Paid</span><br><?= e(money($bal['paid'])) ?></div><div><span class="muted">Balance</span><br><strong><?= e(money($bal['outstanding'])) ?></strong></div><div><span class="muted">Due</span><br><?= $i['due_date'] ? e(local_date($i['due_date'])) : '—' ?><?= $bal['overdue'] ? ' <span class="badge badge-pending">overdue</span>' : '' ?></div></div>
    <?= \Vertex\Core\View::partial('billing-lines', ['items' => $items, 'subtotal' => (int) $i['subtotal_minor'], 'discount' => (int) $i['discount_minor'], 'total' => (int) $i['total_minor']]) ?>
    <?php if ($i['client_notes']) : ?><p class="prewrap"><?= e($i['client_notes']) ?></p><?php endif; ?><p class="muted"><?= e($biz['tax_statement'] ?? 'Tax is not applicable.') ?></p></div>
<?php if ($payments !== []) : ?><div class="panel"><h2>Payments received</h2><ul class="plain-list"><?php foreach ($payments as $p) : ?><li><?= e(money(max(0, $p['gross_minor'] - $p['refunded_minor']))) ?> · <?= e(local_date($p['received_on'])) ?> · <?= e($p['reference']) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if ($payable > 0) : ?><div class="panel"><h2>Pay this invoice</h2>
    <?php if ($upiLink && $upi) : ?><p><a class="btn btn-primary" href="<?= e($upiLink) ?>" rel="noopener">Pay <?= e(money($payable)) ?> with Google Pay</a></p>
        <p class="muted">On your phone this opens Google Pay (or another UPI app) with the amount filled in. On a computer, pay to this UPI ID from your phone: <strong><?= e($upi['upi_id']) ?></strong> (<?= e($upi['payee_name']) ?>), amount <strong><?= e(money($payable)) ?></strong>, note <strong>Invoice <?= e($i['reference']) ?></strong>.</p>
    <?php else : ?><p class="muted">Online payment is not switched on. Please pay using the instructions on the invoice (<?= e($biz['payment_instructions'] ?? 'contact us') ?>), then tell us below.</p><?php endif; ?>
    <?php if (!empty($biz['payment_instructions']) && $upiLink) : ?><p class="muted">Other ways to pay:</p><p class="prewrap"><?= e($biz['payment_instructions']) ?></p><?php endif; ?>
    <h3>After you have paid</h3><p class="muted">Enter the transaction (UTR) number from your payment app. We check it against our bank and confirm here: until then the invoice still shows as unpaid.</p>
    <form method="post" action="<?= e($url) ?>/pay" class="form-grid"><?= csrf_field() ?>
        <div class="field"><label for="am">Amount you paid (₹)</label><input id="am" name="amount" required inputmode="decimal" value="<?= e($v('amount', number_format($payable / 100, 2, '.', ''))) ?>"></div>
        <div class="field"><label for="me">Paid by</label><select id="me" name="method"><option value="upi"<?= $v('method') === 'bank_transfer' ? '' : ' selected' ?>>UPI / Google Pay</option><option value="bank_transfer"<?= $v('method') === 'bank_transfer' ? ' selected' : '' ?>>Bank transfer</option></select></div>
        <div class="field"><label for="re">Transaction / UTR number</label><input id="re" name="reference" required maxlength="40" value="<?= e($v('reference')) ?>"></div>
        <div class="field"><label for="po">Date you paid</label><input id="po" name="paid_on" type="date" required max="<?= e($today) ?>" value="<?= e($v('paid_on', $today)) ?>"></div>
        <div class="form-actions"><button class="btn btn-primary" type="submit">I have paid: send details</button></div></form></div><?php endif; ?>
<?php if ($claims !== []) : ?><div class="panel"><h2>Your submitted payments</h2><ul class="plain-list"><?php foreach ($claims as $c) : ?><li><?= e($c['reference']) ?> · <?= e(money($c['gross_minor'])) ?> · <?= e(local_date($c['received_on'])) ?> · <?= \Vertex\Core\View::partial('pbadge', ['kind' => 'payment', 's' => $c['status']]) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
